SELECT id, app_name, title, content, tags, source, create_time, MATCH(title, content) AGAINST (#{query} IN NATURAL LANGUAGE MODE) AS score FROM ai_knowledge WHERE MATCH(title, content) AGAINST (#{query} IN NATURAL LANGUAGE MODE)
AND (app_name = #{appName} OR app_name = '')
ORDER BY score DESC, create_time DESC LIMIT #{limit}

SELECT id, app_name, title, content, tags, source, create_time, 0 AS score FROM ai_knowledge
AND (app_name = #{appName} OR app_name = '')
ORDER BY create_time DESC LIMIT #{limit}
